def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    guides = []
    for color, cells in comps:
        for cr, cc in cells:
            vertical = {(r, c) for r, c in cells if c == cc}
            horizontal = {(r, c) for r, c in cells if r == cr}
            if (len(vertical) >= 3 and len(horizontal) >= 3 and
                    len(vertical) + len(horizontal) - 1 == len(cells) and
                    all(r == cr or c == cc for r, c in cells)):
                guides.append((len(cells), color, cells, cr, cc))
    if not guides:
        return [row[:] for row in grid]
