    targets = [(min((r-cr)**2 + (c-cc)**2 for r, c in cells), cells)
               for color, cells in comps if cells != guide]
    if not targets:
        return [row[:] for row in grid]
    target = max(targets, key=lambda item: item[0])[1]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out


